/// 真机：AudioService 后台播放 → 产生媒体会话/通知（供 host 取证）
library;

import 'dart:convert';
import 'dart:io';
import 'package:core/core.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';
import 'package:path_provider/path_provider.dart';
import 'package:player/player.dart';

const String _mp3B64 = '';

void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();

  testWidgets('后台播放：媒体会话与通知', (tester) async {
    final tmp = await getTemporaryDirectory();
    final file = File('${tmp.path}/notify_probe.mp3');
    await file.writeAsBytes(base64Decode(_mp3B64));

    final player = PlayerImpl();
    await AudioBackground.init(player);
    final song = Song(
      id: 'notify1',
      sourceId: 'local',
      title: '通知测试',
      artist: '歌手',
      playUrl: Uri.file(file.path).toString(),
    );
    await player.play(song);
    // 标记起播完成，host 据此开始 dumpsys 取证（停留 25s）
    // ignore: avoid_print
    print('E2E_PLAYING');
    for (var i = 0; i < 25; i++) {
      await Future<void>.delayed(const Duration(seconds: 1));
    }
    await player.pause();
    await player.dispose();
    try {
      await file.delete();
    } catch (_) {}
  });
}
